package com.yuegang.zhihui.order.infrastructure;import com.yuegang.zhihui.common.security.InternalServiceSignature;import com.yuegang.zhihui.inventory.api.InventoryCommand;import java.time.*;import org.springframework.web.client.RestClient;public final class InventoryClient{private final RestClient client;private final InternalServiceSignature signatures;public InventoryClient(String base,byte[]secret){client=RestClient.builder().baseUrl(base).build();signatures=new InternalServiceSignature(secret,Clock.systemUTC(),Duration.ofSeconds(30));}public void reserve(InventoryCommand c){post("/internal/v1/inventory/reserve",c);}public void confirm(InventoryCommand c){post("/internal/v1/inventory/confirm",c);}public void release(InventoryCommand c){post("/internal/v1/inventory/release",c);}public void returnSold(InventoryCommand c){post("/internal/v1/inventory/return-sold",c);}private void post(String path,InventoryCommand c){Instant now=Instant.now();var m=new InternalServiceSignature.Metadata("ygh-order-service","POST",path,now);client.post().uri(path).header("X-YGH-Service","ygh-order-service").header("X-YGH-Service-Timestamp",Long.toString(now.toEpochMilli())).header("X-YGH-Service-Signature",signatures.sign(m)).body(c).retrieve().toBodilessEntity();}}
